            {
                index = Mathf.Min(_selectTabIndex + 1, max);
                move = 1;
            }
            else if (IsPushButton(UIManager.StickLLeft, false))
            {
                index = UIManager.Repeat(_selectTabIndex - 1, 0, max);
                move = -1;
            }
            else if (IsRepeatButton(UIManager.StickLLeft, false))
            {
                index = Mathf.Max(_selectTabIndex - 1, 0);
                move = -1;
            }
            else
            {
